const order = ["<header", "<nav", "<main", "<footer"];
let pos = -1;
for (const tag of order) {
  const next = code.toLowerCase().indexOf(tag);
  if (next === -1 || next < pos) {
    throw new Error(`Expected elements in order: header, nav, main, footer (problem at ${tag}).`);
  }
  pos = next;
}

for (const text of ["PetitFour", "Menu", "Order", "Small cakes, big joy", "Baked fresh every morning.", "12 Rue des Lilas, Paris"]) {
  if (!code.includes(text)) {
    throw new Error(`The text "${text}" went missing — keep every line, change only the wrappers.`);
  }
}

if (/<div/i.test(code)) {
  throw new Error("A <div> is still present — every one of the four becomes a semantic element.");
}
